import { motion } from "motion/react";

interface Props {
  totalCountries: number;
}

export default function EmptyState({ totalCountries }: Props) {
  const continents = [
    { emoji: "🌍", label: "Africa" },
    { emoji: "🌏", label: "Asia" },
    { emoji: "🌎", label: "Americas" },
    { emoji: "🏔️", label: "Europe" },
    { emoji: "🏝️", label: "Oceania" },
  ];

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
      className="glass rounded-3xl px-8 py-14 flex flex-col items-center text-center"
    >
      <motion.div
        animate={{ rotate: [0, -8, 8, -4, 0] }}
        transition={{ duration: 2.5, repeat: Infinity, repeatDelay: 4 }}
        className="text-7xl mb-5 select-none"
      >
        🌐
      </motion.div>

      <h2 className="text-2xl font-bold gradient-text mb-2">
        Global Country Explorer
      </h2>
      <p className="text-[var(--text-secondary)] text-sm max-w-sm mb-8">
        Search any country to instantly see its capital, population, currency,
        languages, timezone and more.
      </p>

      {/* Continent chips */}
      <div className="flex flex-wrap justify-center gap-2 mb-8">
        {continents.map(({ emoji, label }, i) => (
          <motion.span
            key={label}
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: 0.1 + i * 0.07 }}
            className="stat-badge rounded-full px-3 py-1 text-xs font-medium flex items-center gap-1.5"
          >
            {emoji} {label}
          </motion.span>
        ))}
      </div>

      <motion.p
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.6 }}
        className="text-xs text-[var(--text-muted)]"
      >
        {totalCountries} countries in the database
      </motion.p>
    </motion.div>
  );
}
